def anti_shuffle(s):
    def sort_word(word):
        return ''.join(sorted(word))

    words = s.split(' ')
    sorted_words = []

    for word in words:
        sorted_words.append(sort_word(word))

    result = []
    j = 0

    for char in s:
        if char == ' ':
            result.append(' ')
        else:
            result.append(sorted_words[j])
            j += 1

    return ''.join(result)

